// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    __InvMutShare share;

    function setUp() public {
        share = new __InvMutShare();
        c = new LiquidityPool(0, bytes16(0), address(this), address(share), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address actor, address to, uint256 amount, bool shareReturns) public {
        vm.assume(actor != address(0));
        share.setReturn(shareReturns);
        vm.prank(actor);
        bool got = c.transfer(to, amount);
        // General rule: c.transfer's return value equals the boolean the share token returned.
        assertTrue(got == shareReturns);
    }
}

contract __InvMutShare {
    bool public ret = true;

    function setReturn(bool r) external { ret = r; }

    function transfer(address, uint256) external view returns (bool) { return ret; }

    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
